public class AnagramCheck {
    public static boolean isAnagram(String first, String second) {
        if (first.length() != second.length()) {
            return false;
        }
        int[] count = new int[26];
        for (int i = 0; i < first.length(); i++) {
            count[first.charAt(i) - 'a']++;
            count[second.charAt(i) - 'a']--;
        }
        for (int value : count) {
            if (value != 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(isAnagram("listen", "silent"));
        System.out.println(isAnagram("rat", "car"));
    }
}

public class BinarySearch {
    public static int search(int[] sorted, int target) {
        int low = 0;
        int high = sorted.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (sorted[mid] == target) {
                return mid;
            } else if (sorted[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] values = {2, 5, 8, 12, 16, 23, 38, 56};
        System.out.println(search(values, 23));
        System.out.println(search(values, 7));
    }
}

public class FirstOccurrence {
    public static int firstIndex(int[] sorted, int target) {
        int low = 0;
        int high = sorted.length - 1;
        int answer = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (sorted[mid] == target) {
                answer = mid;
                high = mid - 1;
            } else if (sorted[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    }

    public static void main(String[] args) {
        int[] values = {1, 3, 3, 3, 7, 9};
        System.out.println(firstIndex(values, 3));
    }
}

import java.util.Arrays;

public class MergeSort {
    public static void mergeSort(int[] values, int left, int right) {
        if (left >= right) {
            return;
        }
        int middle = left + (right - left) / 2;
        mergeSort(values, left, middle);
        mergeSort(values, middle + 1, right);
        merge(values, left, middle, right);
    }

    private static void merge(int[] values, int left, int middle, int right) {
        int[] merged = new int[right - left + 1];
        int i = left;
        int j = middle + 1;
        int k = 0;
        while (i <= middle && j <= right) {
            if (values[i] <= values[j]) {
                merged[k++] = values[i++];
            } else {
                merged[k++] = values[j++];
            }
        }
        while (i <= middle) {
            merged[k++] = values[i++];
        }
        while (j <= right) {
            merged[k++] = values[j++];
        }
        for (int m = 0; m < merged.length; m++) {
            values[left + m] = merged[m];
        }
    }

    public static void main(String[] args) {
        int[] values = {38, 27, 43, 3, 9, 82, 10};
        mergeSort(values, 0, values.length - 1);
        System.out.println(Arrays.toString(values));
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class SortStudents {
    static class Student {
        final String name;
        final int marks;

        Student(String name, int marks) {
            this.name = name;
            this.marks = marks;
        }
    }

    public static void main(String[] args) {
        List<Student> students = new ArrayList<>();
        students.add(new Student("Ravi", 82));
        students.add(new Student("Anu", 91));
        students.add(new Student("Kiran", 82));

        students.sort(Comparator.comparingInt((Student s) -> s.marks).reversed()
                .thenComparing(s -> s.name));

        for (Student s : students) {
            System.out.println(s.name + " " + s.marks);
        }
    }
}

public class SinglyLinkedList {
    static class Node {
        int value;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    private Node head;

    public void addFirst(int value) {
        Node node = new Node(value);
        node.next = head;
        head = node;
    }

    public void addLast(int value) {
        Node node = new Node(value);
        if (head == null) {
            head = node;
            return;
        }
        Node current = head;
        while (current.next != null) {
            current = current.next;
        }
        current.next = node;
    }

    public boolean remove(int value) {
        Node dummy = new Node(0);
        dummy.next = head;
        Node previous = dummy;
        while (previous.next != null) {
            if (previous.next.value == value) {
                previous.next = previous.next.next;
                head = dummy.next;
                return true;
            }
            previous = previous.next;
        }
        return false;
    }

    public void print() {
        StringBuilder out = new StringBuilder();
        for (Node current = head; current != null; current = current.next) {
            out.append(current.value).append(" -> ");
        }
        System.out.println(out.append("null"));
    }

    public static void main(String[] args) {
        SinglyLinkedList list = new SinglyLinkedList();
        list.addLast(20);
        list.addLast(30);
        list.addFirst(10);
        list.print();
        list.remove(20);
        list.print();
    }
}

public class ReverseList {
    static class Node {
        int value;
        Node next;

        Node(int value, Node next) {
            this.value = value;
            this.next = next;
        }
    }

    public static Node reverse(Node head) {
        Node previous = null;
        Node current = head;
        while (current != null) {
            Node nextNode = current.next;
            current.next = previous;
            previous = current;
            current = nextNode;
        }
        return previous;
    }

    public static void main(String[] args) {
        Node head = new Node(1, new Node(2, new Node(3, null)));
        for (Node n = reverse(head); n != null; n = n.next) {
            System.out.print(n.value + " ");
        }
    }
}

public class MiddleNode {
    static class Node {
        int value;
        Node next;

        Node(int value, Node next) {
            this.value = value;
            this.next = next;
        }
    }

    public static Node middle(Node head) {
        Node slow = head;
        Node fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    public static void main(String[] args) {
        Node head = new Node(1, new Node(2, new Node(3, new Node(4, new Node(5, null)))));
        System.out.println(middle(head).value);
    }
}
